PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-01','HSK7-01','HSK 7 · Đề 01','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 01 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-01-q01','seed-hsk7-01',1,'single_choice','Pinyin phù hợp với “差异” là phương án nào?','Pinyin của “差异” là “chāyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khác biệt”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q02','seed-hsk7-01',2,'single_choice','Chọn từ Hán ngữ có nghĩa “động thái”.','Từ phù hợp là “动态”, đọc là dòngtài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q03','seed-hsk7-01',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “关联 — guānlián”, nghĩa là “liên hệ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q04','seed-hsk7-01',4,'single_choice','Từ “适用” gần nghĩa nhất với phương án nào?','“适用” (shìyòng) có nghĩa là “áp dụng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q05','seed-hsk7-01',5,'single_choice','Pinyin phù hợp với “路径” là phương án nào?','Pinyin của “路径” là “lùjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lộ trình”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q06','seed-hsk7-01',6,'single_choice','Chọn từ Hán ngữ có nghĩa “tích hợp”.','Từ phù hợp là “整合”, đọc là zhěnghé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q07','seed-hsk7-01',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “协同 — xiétóng”, nghĩa là “phối hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q08','seed-hsk7-01',8,'single_choice','Từ “概念” gần nghĩa nhất với phương án nào?','“概念” (gàiniàn) có nghĩa là “khái niệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q09','seed-hsk7-01',9,'single_choice','Pinyin phù hợp với “层面” là phương án nào?','Pinyin của “层面” là “céngmiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phương diện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q10','seed-hsk7-01',10,'single_choice','Chọn từ Hán ngữ có nghĩa “hiệu ứng”.','Từ phù hợp là “效应”, đọc là xiàoyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q11','seed-hsk7-01',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “框架 — kuàngjià”, nghĩa là “khung cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q12','seed-hsk7-01',12,'single_choice','Từ “语境” gần nghĩa nhất với phương án nào?','“语境” (yǔjìng) có nghĩa là “ngữ cảnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q13','seed-hsk7-01',13,'single_choice','Pinyin phù hợp với “驱动” là phương án nào?','Pinyin của “驱动” là “qūdòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thúc đẩy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q14','seed-hsk7-01',14,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn biến”.','Từ phù hợp là “演变”, đọc là yǎnbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q15','seed-hsk7-01',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实证 — shízhèng”, nghĩa là “thực chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q16','seed-hsk7-01',16,'single_choice','Từ “本质” gần nghĩa nhất với phương án nào?','“本质” (běnzhì) có nghĩa là “bản chất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q17','seed-hsk7-01',17,'single_choice','Pinyin phù hợp với “优化” là phương án nào?','Pinyin của “优化” là “yōuhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tối ưu hóa”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q18','seed-hsk7-01',18,'single_choice','Chọn từ Hán ngữ có nghĩa “chiều cạnh”.','Từ phù hợp là “维度”, đọc là wéidù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q19','seed-hsk7-01',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “认知 — rènzhī”, nghĩa là “nhận thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-01-q20','seed-hsk7-01',20,'single_choice','Từ “约束” gần nghĩa nhất với phương án nào?','“约束” (yuēshù) có nghĩa là “ràng buộc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
