INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-02','HSK7-02','HSK 7 · Đề 02','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-02-q01','seed-hsk7-02',1,'single_choice','Pinyin phù hợp với “效应” là phương án nào?','Pinyin của “效应” là “xiàoyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu ứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q02','seed-hsk7-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “khung cấu trúc”.','Từ phù hợp là “框架”, đọc là kuàngjià. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q03','seed-hsk7-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “语境 — yǔjìng”, nghĩa là “ngữ cảnh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q04','seed-hsk7-02',4,'single_choice','Từ “驱动” gần nghĩa nhất với phương án nào?','“驱动” (qūdòng) có nghĩa là “thúc đẩy”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q05','seed-hsk7-02',5,'single_choice','Pinyin phù hợp với “演变” là phương án nào?','Pinyin của “演变” là “yǎnbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn biến”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q06','seed-hsk7-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thực chứng”.','Từ phù hợp là “实证”, đọc là shízhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q07','seed-hsk7-02',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “本质 — běnzhì”, nghĩa là “bản chất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q08','seed-hsk7-02',8,'single_choice','Từ “优化” gần nghĩa nhất với phương án nào?','“优化” (yōuhuà) có nghĩa là “tối ưu hóa”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q09','seed-hsk7-02',9,'single_choice','Pinyin phù hợp với “维度” là phương án nào?','Pinyin của “维度” là “wéidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiều cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-02-q10','seed-hsk7-02',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận thức”.','Từ phù hợp là “认知”, đọc là rènzhī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
