INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-03','HSK7-03','HSK 7 · Đề 03','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-03-q01','seed-hsk7-03',1,'single_choice','Pinyin phù hợp với “认知” là phương án nào?','Pinyin của “认知” là “rènzhī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q02','seed-hsk7-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “ràng buộc”.','Từ phù hợp là “约束”, đọc là yuēshù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q03','seed-hsk7-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “差异 — chāyì”, nghĩa là “khác biệt”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q04','seed-hsk7-03',4,'single_choice','Từ “动态” gần nghĩa nhất với phương án nào?','“动态” (dòngtài) có nghĩa là “động thái”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q05','seed-hsk7-03',5,'single_choice','Pinyin phù hợp với “关联” là phương án nào?','Pinyin của “关联” là “guānlián”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên hệ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q06','seed-hsk7-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “áp dụng”.','Từ phù hợp là “适用”, đọc là shìyòng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q07','seed-hsk7-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “路径 — lùjìng”, nghĩa là “lộ trình”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q08','seed-hsk7-03',8,'single_choice','Từ “整合” gần nghĩa nhất với phương án nào?','“整合” (zhěnghé) có nghĩa là “tích hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q09','seed-hsk7-03',9,'single_choice','Pinyin phù hợp với “协同” là phương án nào?','Pinyin của “协同” là “xiétóng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phối hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q10','seed-hsk7-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “khái niệm”.','Từ phù hợp là “概念”, đọc là gàiniàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q11','seed-hsk7-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “层面 — céngmiàn”, nghĩa là “phương diện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q12','seed-hsk7-03',12,'single_choice','Từ “效应” gần nghĩa nhất với phương án nào?','“效应” (xiàoyìng) có nghĩa là “hiệu ứng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q13','seed-hsk7-03',13,'single_choice','Pinyin phù hợp với “框架” là phương án nào?','Pinyin của “框架” là “kuàngjià”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khung cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q14','seed-hsk7-03',14,'single_choice','Chọn từ Hán ngữ có nghĩa “ngữ cảnh”.','Từ phù hợp là “语境”, đọc là yǔjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q15','seed-hsk7-03',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “驱动 — qūdòng”, nghĩa là “thúc đẩy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q16','seed-hsk7-03',16,'single_choice','Từ “演变” gần nghĩa nhất với phương án nào?','“演变” (yǎnbiàn) có nghĩa là “diễn biến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-03-q17','seed-hsk7-03',17,'single_choice','Pinyin phù hợp với “实证” là phương án nào?','Pinyin của “实证” là “shízhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực chứng”.',NULL,NULL,0,1,'',datetime('now')),
