('seed-hsk7-07-q23','seed-hsk7-07',23,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “优化 — yōuhuà”, nghĩa là “tối ưu hóa”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
