INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-08','HSK7-08','HSK 7 · Đề 08','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-08-q01','seed-hsk7-08',1,'single_choice','Pinyin phù hợp với “适用” là phương án nào?','Pinyin của “适用” là “shìyòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “áp dụng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q02','seed-hsk7-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “lộ trình”.','Từ phù hợp là “路径”, đọc là lùjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q03','seed-hsk7-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “整合 — zhěnghé”, nghĩa là “tích hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q04','seed-hsk7-08',4,'single_choice','Từ “协同” gần nghĩa nhất với phương án nào?','“协同” (xiétóng) có nghĩa là “phối hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q05','seed-hsk7-08',5,'single_choice','Pinyin phù hợp với “概念” là phương án nào?','Pinyin của “概念” là “gàiniàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khái niệm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q06','seed-hsk7-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phương diện”.','Từ phù hợp là “层面”, đọc là céngmiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q07','seed-hsk7-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “效应 — xiàoyìng”, nghĩa là “hiệu ứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q08','seed-hsk7-08',8,'single_choice','Từ “框架” gần nghĩa nhất với phương án nào?','“框架” (kuàngjià) có nghĩa là “khung cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q09','seed-hsk7-08',9,'single_choice','Pinyin phù hợp với “语境” là phương án nào?','Pinyin của “语境” là “yǔjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngữ cảnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q10','seed-hsk7-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thúc đẩy”.','Từ phù hợp là “驱动”, đọc là qūdòng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q11','seed-hsk7-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “演变 — yǎnbiàn”, nghĩa là “diễn biến”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q12','seed-hsk7-08',12,'single_choice','Từ “实证” gần nghĩa nhất với phương án nào?','“实证” (shízhèng) có nghĩa là “thực chứng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
