('seed-hsk7-08-q27','seed-hsk7-08',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “效应 — xiàoyìng”, nghĩa là “hiệu ứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q28','seed-hsk7-08',28,'single_choice','Từ “框架” gần nghĩa nhất với phương án nào?','“框架” (kuàngjià) có nghĩa là “khung cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q29','seed-hsk7-08',29,'single_choice','Pinyin phù hợp với “语境” là phương án nào?','Pinyin của “语境” là “yǔjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngữ cảnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-08-q30','seed-hsk7-08',30,'single_choice','Chọn từ Hán ngữ có nghĩa “thúc đẩy”.','Từ phù hợp là “驱动”, đọc là qūdòng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
