('seed-hsk7-09-q30','seed-hsk7-09',30,'single_choice','Chọn từ Hán ngữ có nghĩa “động thái”.','Từ phù hợp là “动态”, đọc là dòngtài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-09-q31','seed-hsk7-09',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “关联 — guānlián”, nghĩa là “liên hệ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-09-q32','seed-hsk7-09',32,'single_choice','Từ “适用” gần nghĩa nhất với phương án nào?','“适用” (shìyòng) có nghĩa là “áp dụng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-09-q33','seed-hsk7-09',33,'single_choice','Pinyin phù hợp với “路径” là phương án nào?','Pinyin của “路径” là “lùjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lộ trình”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-09-q34','seed-hsk7-09',34,'single_choice','Chọn từ Hán ngữ có nghĩa “tích hợp”.','Từ phù hợp là “整合”, đọc là zhěnghé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
