('seed-hsk7-09-q36','seed-hsk7-09',36,'single_choice','Từ “概念” gần nghĩa nhất với phương án nào?','“概念” (gàiniàn) có nghĩa là “khái niệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
