INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-10','HSK7-10','HSK 7 · Đề 10','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 10 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-10-q01','seed-hsk7-10',1,'single_choice','Pinyin phù hợp với “动态” là phương án nào?','Pinyin của “动态” là “dòngtài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “động thái”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q02','seed-hsk7-10',2,'single_choice','Chọn từ Hán ngữ có nghĩa “liên hệ”.','Từ phù hợp là “关联”, đọc là guānlián. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q03','seed-hsk7-10',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适用 — shìyòng”, nghĩa là “áp dụng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q04','seed-hsk7-10',4,'single_choice','Từ “路径” gần nghĩa nhất với phương án nào?','“路径” (lùjìng) có nghĩa là “lộ trình”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q05','seed-hsk7-10',5,'single_choice','Pinyin phù hợp với “整合” là phương án nào?','Pinyin của “整合” là “zhěnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q06','seed-hsk7-10',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phối hợp”.','Từ phù hợp là “协同”, đọc là xiétóng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q07','seed-hsk7-10',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “概念 — gàiniàn”, nghĩa là “khái niệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q08','seed-hsk7-10',8,'single_choice','Từ “层面” gần nghĩa nhất với phương án nào?','“层面” (céngmiàn) có nghĩa là “phương diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q09','seed-hsk7-10',9,'single_choice','Pinyin phù hợp với “效应” là phương án nào?','Pinyin của “效应” là “xiàoyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu ứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q10','seed-hsk7-10',10,'single_choice','Chọn từ Hán ngữ có nghĩa “khung cấu trúc”.','Từ phù hợp là “框架”, đọc là kuàngjià. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
