('seed-hsk7-10-q34','seed-hsk7-10',34,'single_choice','Chọn từ Hán ngữ có nghĩa “thực chứng”.','Từ phù hợp là “实证”, đọc là shízhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q35','seed-hsk7-10',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “本质 — běnzhì”, nghĩa là “bản chất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q36','seed-hsk7-10',36,'single_choice','Từ “优化” gần nghĩa nhất với phương án nào?','“优化” (yōuhuà) có nghĩa là “tối ưu hóa”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q37','seed-hsk7-10',37,'single_choice','Pinyin phù hợp với “维度” là phương án nào?','Pinyin của “维度” là “wéidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiều cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q38','seed-hsk7-10',38,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận thức”.','Từ phù hợp là “认知”, đọc là rènzhī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q39','seed-hsk7-10',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “约束 — yuēshù”, nghĩa là “ràng buộc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q40','seed-hsk7-10',40,'single_choice','Từ “差异” gần nghĩa nhất với phương án nào?','“差异” (chāyì) có nghĩa là “khác biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q41','seed-hsk7-10',41,'single_choice','Pinyin phù hợp với “动态” là phương án nào?','Pinyin của “动态” là “dòngtài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “động thái”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q42','seed-hsk7-10',42,'single_choice','Chọn từ Hán ngữ có nghĩa “liên hệ”.','Từ phù hợp là “关联”, đọc là guānlián. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q43','seed-hsk7-10',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适用 — shìyòng”, nghĩa là “áp dụng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q44','seed-hsk7-10',44,'single_choice','Từ “路径” gần nghĩa nhất với phương án nào?','“路径” (lùjìng) có nghĩa là “lộ trình”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q45','seed-hsk7-10',45,'single_choice','Pinyin phù hợp với “整合” là phương án nào?','Pinyin của “整合” là “zhěnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q46','seed-hsk7-10',46,'single_choice','Chọn từ Hán ngữ có nghĩa “phối hợp”.','Từ phù hợp là “协同”, đọc là xiétóng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q47','seed-hsk7-10',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “概念 — gàiniàn”, nghĩa là “khái niệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q48','seed-hsk7-10',48,'single_choice','Từ “层面” gần nghĩa nhất với phương án nào?','“层面” (céngmiàn) có nghĩa là “phương diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-10-q49','seed-hsk7-10',49,'single_choice','Pinyin phù hợp với “效应” là phương án nào?','Pinyin của “效应” là “xiàoyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu ứng”.',NULL,NULL,0,1,'',datetime('now')),
