INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-11','HSK7-11','HSK 7 · Đề 11','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 11 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-11-q01','seed-hsk7-11',1,'single_choice','Pinyin phù hợp với “框架” là phương án nào?','Pinyin của “框架” là “kuàngjià”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khung cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q02','seed-hsk7-11',2,'single_choice','Chọn từ Hán ngữ có nghĩa “ngữ cảnh”.','Từ phù hợp là “语境”, đọc là yǔjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q03','seed-hsk7-11',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “驱动 — qūdòng”, nghĩa là “thúc đẩy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q04','seed-hsk7-11',4,'single_choice','Từ “演变” gần nghĩa nhất với phương án nào?','“演变” (yǎnbiàn) có nghĩa là “diễn biến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q05','seed-hsk7-11',5,'single_choice','Pinyin phù hợp với “实证” là phương án nào?','Pinyin của “实证” là “shízhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực chứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q06','seed-hsk7-11',6,'single_choice','Chọn từ Hán ngữ có nghĩa “bản chất”.','Từ phù hợp là “本质”, đọc là běnzhì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q07','seed-hsk7-11',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “优化 — yōuhuà”, nghĩa là “tối ưu hóa”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q08','seed-hsk7-11',8,'single_choice','Từ “维度” gần nghĩa nhất với phương án nào?','“维度” (wéidù) có nghĩa là “chiều cạnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q09','seed-hsk7-11',9,'single_choice','Pinyin phù hợp với “认知” là phương án nào?','Pinyin của “认知” là “rènzhī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận thức”.',NULL,NULL,0,1,'',datetime('now')),
