('seed-hsk7-11-q38','seed-hsk7-11',38,'single_choice','Chọn từ Hán ngữ có nghĩa “khái niệm”.','Từ phù hợp là “概念”, đọc là gàiniàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q39','seed-hsk7-11',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “层面 — céngmiàn”, nghĩa là “phương diện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q40','seed-hsk7-11',40,'single_choice','Từ “效应” gần nghĩa nhất với phương án nào?','“效应” (xiàoyìng) có nghĩa là “hiệu ứng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q41','seed-hsk7-11',41,'single_choice','Pinyin phù hợp với “框架” là phương án nào?','Pinyin của “框架” là “kuàngjià”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khung cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q42','seed-hsk7-11',42,'single_choice','Chọn từ Hán ngữ có nghĩa “ngữ cảnh”.','Từ phù hợp là “语境”, đọc là yǔjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q43','seed-hsk7-11',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “驱动 — qūdòng”, nghĩa là “thúc đẩy”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q44','seed-hsk7-11',44,'single_choice','Từ “演变” gần nghĩa nhất với phương án nào?','“演变” (yǎnbiàn) có nghĩa là “diễn biến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q45','seed-hsk7-11',45,'single_choice','Pinyin phù hợp với “实证” là phương án nào?','Pinyin của “实证” là “shízhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực chứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q46','seed-hsk7-11',46,'single_choice','Chọn từ Hán ngữ có nghĩa “bản chất”.','Từ phù hợp là “本质”, đọc là běnzhì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q47','seed-hsk7-11',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “优化 — yōuhuà”, nghĩa là “tối ưu hóa”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q48','seed-hsk7-11',48,'single_choice','Từ “维度” gần nghĩa nhất với phương án nào?','“维度” (wéidù) có nghĩa là “chiều cạnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q49','seed-hsk7-11',49,'single_choice','Pinyin phù hợp với “认知” là phương án nào?','Pinyin của “认知” là “rènzhī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-11-q50','seed-hsk7-11',50,'single_choice','Chọn từ Hán ngữ có nghĩa “ràng buộc”.','Từ phù hợp là “约束”, đọc là yuēshù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
