('seed-hsk7-12-q42','seed-hsk7-12',42,'single_choice','Chọn từ Hán ngữ có nghĩa “khác biệt”.','Từ phù hợp là “差异”, đọc là chāyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q43','seed-hsk7-12',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “动态 — dòngtài”, nghĩa là “động thái”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q44','seed-hsk7-12',44,'single_choice','Từ “关联” gần nghĩa nhất với phương án nào?','“关联” (guānlián) có nghĩa là “liên hệ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q45','seed-hsk7-12',45,'single_choice','Pinyin phù hợp với “适用” là phương án nào?','Pinyin của “适用” là “shìyòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “áp dụng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q46','seed-hsk7-12',46,'single_choice','Chọn từ Hán ngữ có nghĩa “lộ trình”.','Từ phù hợp là “路径”, đọc là lùjìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q47','seed-hsk7-12',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “整合 — zhěnghé”, nghĩa là “tích hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q48','seed-hsk7-12',48,'single_choice','Từ “协同” gần nghĩa nhất với phương án nào?','“协同” (xiétóng) có nghĩa là “phối hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q49','seed-hsk7-12',49,'single_choice','Pinyin phù hợp với “概念” là phương án nào?','Pinyin của “概念” là “gàiniàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khái niệm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-12-q50','seed-hsk7-12',50,'single_choice','Chọn từ Hán ngữ có nghĩa “phương diện”.','Từ phù hợp là “层面”, đọc là céngmiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
