INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-13','HSK7-13','HSK 7 · Đề 13','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-13-q01','seed-hsk7-13',1,'single_choice','Pinyin phù hợp với “层面” là phương án nào?','Pinyin của “层面” là “céngmiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phương diện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q02','seed-hsk7-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “hiệu ứng”.','Từ phù hợp là “效应”, đọc là xiàoyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q03','seed-hsk7-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “框架 — kuàngjià”, nghĩa là “khung cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q04','seed-hsk7-13',4,'single_choice','Từ “语境” gần nghĩa nhất với phương án nào?','“语境” (yǔjìng) có nghĩa là “ngữ cảnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q05','seed-hsk7-13',5,'single_choice','Pinyin phù hợp với “驱动” là phương án nào?','Pinyin của “驱动” là “qūdòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thúc đẩy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q06','seed-hsk7-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn biến”.','Từ phù hợp là “演变”, đọc là yǎnbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q07','seed-hsk7-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实证 — shízhèng”, nghĩa là “thực chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q08','seed-hsk7-13',8,'single_choice','Từ “本质” gần nghĩa nhất với phương án nào?','“本质” (běnzhì) có nghĩa là “bản chất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q09','seed-hsk7-13',9,'single_choice','Pinyin phù hợp với “优化” là phương án nào?','Pinyin của “优化” là “yōuhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tối ưu hóa”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q10','seed-hsk7-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “chiều cạnh”.','Từ phù hợp là “维度”, đọc là wéidù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q11','seed-hsk7-13',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “认知 — rènzhī”, nghĩa là “nhận thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q12','seed-hsk7-13',12,'single_choice','Từ “约束” gần nghĩa nhất với phương án nào?','“约束” (yuēshù) có nghĩa là “ràng buộc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q13','seed-hsk7-13',13,'single_choice','Pinyin phù hợp với “差异” là phương án nào?','Pinyin của “差异” là “chāyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khác biệt”.',NULL,NULL,0,1,'',datetime('now')),
