('seed-hsk7-13-q45','seed-hsk7-13',45,'single_choice','Pinyin phù hợp với “驱动” là phương án nào?','Pinyin của “驱动” là “qūdòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thúc đẩy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q46','seed-hsk7-13',46,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn biến”.','Từ phù hợp là “演变”, đọc là yǎnbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q47','seed-hsk7-13',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实证 — shízhèng”, nghĩa là “thực chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q48','seed-hsk7-13',48,'single_choice','Từ “本质” gần nghĩa nhất với phương án nào?','“本质” (běnzhì) có nghĩa là “bản chất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q49','seed-hsk7-13',49,'single_choice','Pinyin phù hợp với “优化” là phương án nào?','Pinyin của “优化” là “yōuhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tối ưu hóa”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-13-q50','seed-hsk7-13',50,'single_choice','Chọn từ Hán ngữ có nghĩa “chiều cạnh”.','Từ phù hợp là “维度”, đọc là wéidù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
