INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-14','HSK7-14','HSK 7 · Đề 14','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 14 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-14-q01','seed-hsk7-14',1,'single_choice','Pinyin phù hợp với “维度” là phương án nào?','Pinyin của “维度” là “wéidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiều cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q02','seed-hsk7-14',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận thức”.','Từ phù hợp là “认知”, đọc là rènzhī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q03','seed-hsk7-14',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “约束 — yuēshù”, nghĩa là “ràng buộc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q04','seed-hsk7-14',4,'single_choice','Từ “差异” gần nghĩa nhất với phương án nào?','“差异” (chāyì) có nghĩa là “khác biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q05','seed-hsk7-14',5,'single_choice','Pinyin phù hợp với “动态” là phương án nào?','Pinyin của “动态” là “dòngtài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “động thái”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q06','seed-hsk7-14',6,'single_choice','Chọn từ Hán ngữ có nghĩa “liên hệ”.','Từ phù hợp là “关联”, đọc là guānlián. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q07','seed-hsk7-14',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适用 — shìyòng”, nghĩa là “áp dụng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q08','seed-hsk7-14',8,'single_choice','Từ “路径” gần nghĩa nhất với phương án nào?','“路径” (lùjìng) có nghĩa là “lộ trình”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q09','seed-hsk7-14',9,'single_choice','Pinyin phù hợp với “整合” là phương án nào?','Pinyin của “整合” là “zhěnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q10','seed-hsk7-14',10,'single_choice','Chọn từ Hán ngữ có nghĩa “phối hợp”.','Từ phù hợp là “协同”, đọc là xiétóng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q11','seed-hsk7-14',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “概念 — gàiniàn”, nghĩa là “khái niệm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q12','seed-hsk7-14',12,'single_choice','Từ “层面” gần nghĩa nhất với phương án nào?','“层面” (céngmiàn) có nghĩa là “phương diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q13','seed-hsk7-14',13,'single_choice','Pinyin phù hợp với “效应” là phương án nào?','Pinyin của “效应” là “xiàoyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hiệu ứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q14','seed-hsk7-14',14,'single_choice','Chọn từ Hán ngữ có nghĩa “khung cấu trúc”.','Từ phù hợp là “框架”, đọc là kuàngjià. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q15','seed-hsk7-14',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “语境 — yǔjìng”, nghĩa là “ngữ cảnh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q16','seed-hsk7-14',16,'single_choice','Từ “驱动” gần nghĩa nhất với phương án nào?','“驱动” (qūdòng) có nghĩa là “thúc đẩy”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q17','seed-hsk7-14',17,'single_choice','Pinyin phù hợp với “演变” là phương án nào?','Pinyin của “演变” là “yǎnbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn biến”.',NULL,NULL,0,1,'',datetime('now')),
