('seed-hsk7-14-q49','seed-hsk7-14',49,'single_choice','Pinyin phù hợp với “整合” là phương án nào?','Pinyin của “整合” là “zhěnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-14-q50','seed-hsk7-14',50,'single_choice','Chọn từ Hán ngữ có nghĩa “phối hợp”.','Từ phù hợp là “协同”, đọc là xiétóng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
