INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-17','HSK7-17','HSK 7 · Đề 17','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 17 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-17-q01','seed-hsk7-17',1,'single_choice','Pinyin phù hợp với “路径” là phương án nào?','Pinyin của “路径” là “lùjìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lộ trình”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q02','seed-hsk7-17',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tích hợp”.','Từ phù hợp là “整合”, đọc là zhěnghé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q03','seed-hsk7-17',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “协同 — xiétóng”, nghĩa là “phối hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q04','seed-hsk7-17',4,'single_choice','Từ “概念” gần nghĩa nhất với phương án nào?','“概念” (gàiniàn) có nghĩa là “khái niệm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q05','seed-hsk7-17',5,'single_choice','Pinyin phù hợp với “层面” là phương án nào?','Pinyin của “层面” là “céngmiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phương diện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q06','seed-hsk7-17',6,'single_choice','Chọn từ Hán ngữ có nghĩa “hiệu ứng”.','Từ phù hợp là “效应”, đọc là xiàoyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q07','seed-hsk7-17',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “框架 — kuàngjià”, nghĩa là “khung cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q08','seed-hsk7-17',8,'single_choice','Từ “语境” gần nghĩa nhất với phương án nào?','“语境” (yǔjìng) có nghĩa là “ngữ cảnh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q09','seed-hsk7-17',9,'single_choice','Pinyin phù hợp với “驱动” là phương án nào?','Pinyin của “驱动” là “qūdòng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thúc đẩy”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q10','seed-hsk7-17',10,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn biến”.','Từ phù hợp là “演变”, đọc là yǎnbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q11','seed-hsk7-17',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实证 — shízhèng”, nghĩa là “thực chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q12','seed-hsk7-17',12,'single_choice','Từ “本质” gần nghĩa nhất với phương án nào?','“本质” (běnzhì) có nghĩa là “bản chất”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-17-q13','seed-hsk7-17',13,'single_choice','Pinyin phù hợp với “优化” là phương án nào?','Pinyin của “优化” là “yōuhuà”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tối ưu hóa”.',NULL,NULL,0,1,'',datetime('now')),
