INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk7-18','HSK7-18','HSK 7 · Đề 18','hsk','HSK 7',90,'published',1,'Đề luyện HSK 7 số 18 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk7-18-q01','seed-hsk7-18',1,'single_choice','Pinyin phù hợp với “演变” là phương án nào?','Pinyin của “演变” là “yǎnbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn biến”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q02','seed-hsk7-18',2,'single_choice','Chọn từ Hán ngữ có nghĩa “thực chứng”.','Từ phù hợp là “实证”, đọc là shízhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q03','seed-hsk7-18',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “本质 — běnzhì”, nghĩa là “bản chất”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q04','seed-hsk7-18',4,'single_choice','Từ “优化” gần nghĩa nhất với phương án nào?','“优化” (yōuhuà) có nghĩa là “tối ưu hóa”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q05','seed-hsk7-18',5,'single_choice','Pinyin phù hợp với “维度” là phương án nào?','Pinyin của “维度” là “wéidù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiều cạnh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q06','seed-hsk7-18',6,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận thức”.','Từ phù hợp là “认知”, đọc là rènzhī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q07','seed-hsk7-18',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “约束 — yuēshù”, nghĩa là “ràng buộc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q08','seed-hsk7-18',8,'single_choice','Từ “差异” gần nghĩa nhất với phương án nào?','“差异” (chāyì) có nghĩa là “khác biệt”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q09','seed-hsk7-18',9,'single_choice','Pinyin phù hợp với “动态” là phương án nào?','Pinyin của “动态” là “dòngtài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “động thái”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q10','seed-hsk7-18',10,'single_choice','Chọn từ Hán ngữ có nghĩa “liên hệ”.','Từ phù hợp là “关联”, đọc là guānlián. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q11','seed-hsk7-18',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “适用 — shìyòng”, nghĩa là “áp dụng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q12','seed-hsk7-18',12,'single_choice','Từ “路径” gần nghĩa nhất với phương án nào?','“路径” (lùjìng) có nghĩa là “lộ trình”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 7.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q13','seed-hsk7-18',13,'single_choice','Pinyin phù hợp với “整合” là phương án nào?','Pinyin của “整合” là “zhěnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tích hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk7-18-q14','seed-hsk7-18',14,'single_choice','Chọn từ Hán ngữ có nghĩa “phối hợp”.','Từ phù hợp là “协同”, đọc là xiétóng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
